  it('answers an empty session_list when createMessageHandler is called without a sessionStore', async () => {
    const h = harness([]);

    await h.send({type: 'list_sessions'});

    expect(h.sent).toEqual([{type: 'session_list', sessions: []}]);
  });

  describe('when listFor fails', () => {
    const errors = captureErrors();

    it('logs a ws error with userId and error and sends SERVER_ERROR when listFor throws or rejects', async () => {
      const rejectingStore = {
        listFor: () => Promise.reject(new Error('database offline')),
      } as unknown as SessionStore;
      const throwingStore = {
        listFor: () => {
          throw new Error('sync boom');
        },
      } as unknown as SessionStore;

      const sent: OutgoingMessage[] = [];
      const ws = {send: (raw: string) => sent.push(JSON.parse(raw) as OutgoingMessage)} as unknown as WebSocket;
      const orchestrator = {processMessageStream: jest.fn()} as unknown as ChatOrchestrator;
      const session: ChatSession = {sessionId: 's1', userId: 'u1', entries: []};

      await createMessageHandler(orchestrator, rejectingStore)(ws, session, {type: 'list_sessions'});
      await createMessageHandler(orchestrator, throwingStore)(ws, session, {type: 'list_sessions'});

      expect({
        frames: sent.map(frame => (frame.type === 'error' ? {type: frame.type, code: frame.code} : frame)),
        errors,
      }).toEqual({
        frames: [
          {type: 'error', code: 'SERVER_ERROR'},
          {type: 'error', code: 'SERVER_ERROR'},
        ],
        errors: [
          {category: 'ws', message: expect.any(String), userId: 'u1', error: 'database offline'},
          {category: 'ws', message: expect.any(String), userId: 'u1', error: 'sync boom'},
        ],
      });
    });
  });
});

async function handleListSessions(
  ws: WebSocket,
  session: ChatSession,
  message: ListSessionsMessage,
  sessionStore?: SessionStore
): Promise<void> {
  try {
    const summaries =
      (await sessionStore?.listFor?.(session.userId, {limit: message.limit, before: message.before})) ?? [];
    const sessions: SessionSummaryFrame[] = summaries.map(summary => ({
      sessionId: summary.sessionId,
      createdAt: summary.createdAt.toISOString(),
      updatedAt: summary.updatedAt.toISOString(),
      entryCount: summary.entryCount,
    }));
    sendJson(ws, {type: 'session_list', sessions});
  } catch (error) {
    const reason = error instanceof Error ? error.message : String(error);
    log.error('ws', 'session list failed', {userId: session.userId, error: reason});
    sendError(ws, ErrorCodes.SERVER_ERROR, 'Failed to list sessions');
  }
}

